def isBipartite(graph: list[list[int]]) -> bool:
    n = len(graph)
    color = [-1] * n
    from collections import deque
    for i in range(n):
        if color[i] != -1: continue
        color[i] = 0
        q = deque([i])
        while q:
            u = q.popleft()
            for v in graph[u]:
                if color[v] == -1:
                    color[v] = 1 - color[u]
                    q.append(v)
                elif color[v] == color[u]:
                    return False
    return True

